index 872fd69..2acd547 100644
--- a/src/runner/dependency.rs
+++ b/src/runner/dependency.rs
@@ -688,4 +688,199 @@ mod tests {

         assert!(skipped.is_empty());
     }
+
+    // --- Circular reference tests ---
+
+    #[test]
+    fn transitive_dependents_two_node_cycle_terminates() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let deps = graph.transitive_dependents("a");
+        assert!(deps.contains("b"));
+        // "a" is its own transitive dependent via the cycle
+        assert!(deps.contains("a"));
+    }
+
+    #[test]
+    fn transitive_dependents_three_node_cycle_terminates() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["c".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec!["b".to_string()])
+            .build()
+            .unwrap();
+
+        let deps = graph.transitive_dependents("a");
+        assert!(deps.contains("a"));
+        assert!(deps.contains("b"));
+        assert!(deps.contains("c"));
+    }
+
+    #[test]
+    fn transitive_dependents_self_cycle_terminates() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let deps = graph.transitive_dependents("a");
+        assert!(deps.contains("a"));
+    }
+
+    #[test]
+    fn transitive_dependents_cycle_with_tail() {
+        // d -> c -> b -> a -> b (cycle between a and b, c and d are a tail)
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec!["b".to_string()])
+            .add_step("d", vec!["c".to_string()])
+            .build()
+            .unwrap();
+
+        // Dependents of "a" should include b (direct via cycle), plus c and d
+        let deps = graph.transitive_dependents("a");
+        assert!(deps.contains("b"));
+        assert!(deps.contains("a")); // via cycle
+        assert!(deps.contains("c"));
+        assert!(deps.contains("d"));
+    }
+
+    #[test]
+    fn compute_skips_with_dependents_handles_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec!["b".to_string()])
+            .build()
+            .unwrap();
+
+        let mut skip = HashSet::new();
+        skip.insert("a".to_string());
+
+        let skipped = graph.compute_skips(&skip, SkipBehavior::SkipWithDependents);
+        assert!(skipped.contains("a"));
+        assert!(skipped.contains("b"));
+        assert!(skipped.contains("c"));
+    }
+
+    #[test]
+    fn topological_order_three_node_cycle_returns_error() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["c".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec!["b".to_string()])
+            .build()
+            .unwrap();
+
+        let result = graph.topological_order();
+        assert!(result.is_err());
+        let err = result.unwrap_err().to_string();
+        assert!(err.contains("Circular dependency"));
+    }
+
+    #[test]
+    fn topological_order_cycle_in_larger_graph() {
+        // Acyclic portion: x -> y, plus a cycle: a -> b -> a
+        let graph = DependencyGraph::builder()
+            .add_step("x", vec![])
+            .add_step("y", vec!["x".to_string()])
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let result = graph.topological_order();
+        assert!(result.is_err());
+        let err = result.unwrap_err().to_string();
+        assert!(err.contains("Circular dependency"));
+    }
+
+    #[test]
+    fn topological_order_self_cycle_returns_error() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let result = graph.topological_order();
+        assert!(result.is_err());
+    }
+
+    #[test]
+    fn parallel_groups_cycle_returns_error() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let result = graph.parallel_groups();
+        assert!(result.is_err());
+        let err = result.unwrap_err().to_string();
+        assert!(err.contains("Circular dependency"));
+    }
+
+    #[test]
+    fn find_cycle_self_loop_path() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let cycle = graph.find_cycle().unwrap();
+        assert_eq!(cycle.first(), cycle.last());
+        assert!(cycle.contains(&"a".to_string()));
+    }
+
+    #[test]
+    fn find_cycle_ignores_acyclic_portion() {
+        let graph = DependencyGraph::builder()
+            .add_step("x", vec![])
+            .add_step("y", vec!["x".to_string()])
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let cycle = graph.find_cycle().unwrap();
+        // Cycle path should not include x or y
+        assert!(!cycle.contains(&"x".to_string()));
+        assert!(!cycle.contains(&"y".to_string()));
+    }
+
+    #[test]
+    fn is_ready_step_in_cycle_not_ready() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        // Neither step can ever be ready without the other completing first
+        assert!(!graph.is_ready("a", &HashSet::new()));
+        assert!(!graph.is_ready("b", &HashSet::new()));
+    }
+
+    #[test]
+    fn topological_order_error_includes_cycle_participants() {
+        let graph = DependencyGraph::builder()
+            .add_step("x", vec![])
+            .add_step("a", vec!["c".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec!["b".to_string()])
+            .build()
+            .unwrap();
+
+        let err = graph.topological_order().unwrap_err().to_string();
+        // Error should mention the cycle participants, not the acyclic node
+        assert!(err.contains("a"));
+        assert!(err.contains("b"));
+        assert!(err.contains("c"));
+        assert!(!err.contains("x"));
+    }
 }

